#include "stdafx.h"#include "ModelMessages.h"#include <Connect.h>#include <macros/AutoCloser.h>BOOL APIENTRY DllMain( HMODULE hModule,                      DWORD  ul_reason_for_call,                      LPVOID lpReserved ){  return TRUE;}extern "C" Q_DECL_EXPORT         IBaseModel* CreateObject( LPCSTR ObjName ){  return new CMessagesW(ObjName);}CMessagesW* g_pMessageOG = NULL;void MessagingUser( char *pMessage, COLORREF clrBkg, COLORREF clrTxt ){  if( !g_pMessageOG )    return;  CModel2OperatorMessages mes;  mes.clrBkg = clrBkg;  mes.clrTxt = clrTxt;  mes.nFlag = 0;  strcpy_s( mes.szText, pMessage );    g_pMessageOG->WriteMessage( &mes );}//////////////////////////////////////////////////////////////////////////CMessagesW::CMessagesW( LPCTSTR _ObjName ) : IBaseModel ((char*)_ObjName), m_pSystem(NULL)//, m_hMapHead(NULL), m_hMapData(NULL)//, m_pHeadT(NULL), m_pDataT(NULL), pbBegWnd(NULL)//{  SYSTEM_INFO SI;  GetSystemInfo( &SI );  m_dwAllocKvant = SI.dwAllocationGranularity;  m_dwCountKvant = m_dwAllocKvant/sizeof(CModel2OperatorMessages);  ASS( m_dwAllocKvant == m_dwCountKvant*sizeof(CModel2OperatorMessages) );  TypeObj = RSU_Obj;  pMessagingUser = MessagingUser;}CMessagesW::~CMessagesW(){  g_pMessageOG = NULL;  if( pbBegWnd )    ::UnmapViewOfFile( pbBegWnd );  if( m_pHeadT )    ::UnmapViewOfFile( m_pHeadT );  if( m_hMapHead )    ::CloseHandle( m_hMapHead );  if( m_hMapData )    ::CloseHandle( m_hMapData );}int CMessagesW::Init( int j ){  m_pSystem = GetSystemData();  m_pSystem->nMsgToOperator = 0;  if( !OpenMessageHead() )     return 1;  if( !OpenMessageData() )     return 1;  //  g_pMessageOG = this;  //  return 0;}int CMessagesW::RestoreState( char * StrName ){  return 0;}// Запись в файлvoid CMessagesW::WriteMessage(CModel2OperatorMessages* pMessage){  if( (m_pSystem->nMsgToOperator % m_dwCountKvant) == 0 )  {    // Смена окна    ::UnmapViewOfFile( pbBegWnd );    if ( pbBegWnd != NULL )    {      m_pHeadT->dwName++;      OpenMessageData();    }    pbBegWnd = MapView( m_hMapData, m_pHeadT->dwName*m_dwAllocKvant, m_dwAllocKvant );    ASS(pbBegWnd != NULL);    m_pDataT = (CModel2OperatorMessages*)(pbBegWnd);    memset( m_pDataT, 0, m_dwAllocKvant );  }  pMessage->nTime  = (int)m_pSystem->TimeB();  memcpy( m_pDataT, pMessage, sizeof(CModel2OperatorMessages) );  m_pDataT++;  m_pSystem->nMsgToOperator++;  m_pHeadT->dwCount++;}